def plan(n_points, est_matches, vec_kb, cfg):
    # small result: read ids from payload index, score them all
    if est_matches * vec_kb < cfg.full_scan_threshold_kb:
        return "payload index + exact scan"
    selectivity = est_matches / n_points
    # few matches relative to the graph, but too many to scan
    if cfg.acorn_enable and selectivity < cfg.acorn_max_selectivity:
        return "ACORN filtered HNSW"
    return "filtered HNSW"
